// 真实本域writer与Common缓存分配验证永久提交边界；typed成功effect读不冒World运行。
#define POLITICAL_SUCCESSION_NOMINATION_FIXTURE_ONLY
#include "political_succession_nomination_test.cpp"
#undef POLITICAL_SUCCESSION_NOMINATION_FIXTURE_ONLY
#include "resident/domains/politics/succession/political_succession_receipts.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
namespace {
struct SuccessionReceiptFixture:NominationFixture {
 PoliticalSuccessionState all;
 // 原请求序号/结果revision/全局history实际分配后才绑定业务源。
 StableId commit(const StableId& actor,PoliticalSuccessionNominationCommand command,Integer request){auto before=all;auto id=submit(actor,command);all.nominations=nominations;auto kind=std::visit([](const auto& v){return political_succession_command_kind(PoliticalSuccessionCommand{v});},command);check(take(political_succession_new_player_source(before,all,actor,kind,common.tick()))==id,"actual unique business source selected");auto r=std::make_shared<CommitResult>();r->ok=true;r->kind=kind;r->tick=common.tick();r->revision=++common.state().identity.revision;r->result_id=take(common.next_id("result"));common.state().request_sequences.set(actor,request);common.state().results.insert(actor+":"+std::to_string(request),r);common.state().history.push_back({r->tick,r->kind,actor,r->result_id,{}});check(bind_political_succession_player_result(common,all,id,actor,request,*r,[&](const CommitResult&,const StableId& source,const StableId& office){return source==id&&office.empty();}).ok,"real cache object binds exact source");nominations=all.nominations;return id;}
 Status valid(){return validate_political_succession_player_results(common,all,[](const CommitResult&,const StableId&,const StableId& office){return office.empty();});}
};
}
#ifndef POLITICAL_SUCCESSION_RECEIPTS_FIXTURE_ONLY
int main(){try{
 SuccessionReceiptFixture f;auto first=f.commit("leader",f.proposal(),1);auto decline=f.commit("candidate",PoliticalAnswerSuccession{first,false},1);auto second=f.commit("leader",f.proposal(),2);auto later=f.commit("candidate",PoliticalAnswerSuccession{second,false},2);check(f.valid().ok,"interleaved actors retain unique actual results");
 auto raw=encode_political_succession_state(f.all);auto decoded=take(decode_political_succession_state(raw));check(compare_boundary(raw,encode_political_succession_state(decoded)).exact(),"strict new state JSON preserves bindings");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);take(visit_political_succession_checkpoint(writer,decoded));take(writer.finish());const auto& fixed=bytes;CodecVisitor reader(fixed);PoliticalSuccessionState restored;take(visit_political_succession_checkpoint(reader,restored));take(reader.finish());check(compare_boundary(raw,encode_political_succession_state(restored)).exact(),"new independent binary tail preserves exact state");
 auto saved=f.all;auto common=f.common.state();auto last=*f.common.state().results.find("candidate:2");f.common.state().results={};f.common.state().results.insert("candidate:2",last);f.common.state().history.erase(f.common.state().history.begin(),f.common.state().history.end()-1);check(f.valid().ok,"only last true cache/history may remain");f.all.nominations.answers.erase(later);f.common.state().facts.erase(later);check(!f.valid().ok,"deleted later payload/header cannot hang first retained result on old same-tick decline");
 f.all=saved;f.common.state()=common;f.all.nominations.answers.find(later)->player_receipt.reset();check(!f.valid().ok,"no empty receipt becomes an NPC source");auto copied=*last;check(!bind_political_succession_player_result(f.common,f.all,later,"candidate",2,copied,[](const auto&,const auto&,const auto&){return true;}).ok,"identical result copy is not original cache object");check(!f.all.nominations.answers.find(later)->player_receipt,"failed actual-result check has no partial write");check(bind_political_succession_player_result(f.common,f.all,later,"candidate",2,*last,[](const auto&,const auto&,const auto&){return true;}).ok,"original actual result completes only its pending binding");
 check(!political_succession_new_player_source(f.all,f.all,"candidate",political_succession_answer_command,0).ok,"request replay never invents a new source");check(!validate_political_succession_player_results(f.common,f.all,[](const auto&,const auto&,const auto&){return false;}).ok,"wrong typed effect cannot borrow successful command name");auto before_new=f.all;auto next_id=f.submit("leader",f.proposal());auto modified=f.all;modified.nominations=f.nominations;modified.nominations.nominations.find(first)->candidate_actor_id="deputy";check(!political_succession_new_player_source(before_new,modified,"leader",political_succession_nominate_command,0).ok,"one genuine new nomination still cannot mutate an old bound source");f.common.state()=common;f.nominations=f.all.nominations;
 f.all.nominations.answers.find(later)->player_receipt=f.all.nominations.answers.find(decline)->player_receipt;check(!f.valid().ok,"two original answers cannot share one actual result");restored.version=2;check(!decode_political_succession_state(encode_political_succession_state(restored)).ok,"unknown new segment version rejected");
 for(const PoliticalSuccessionCommand& command:std::vector<PoliticalSuccessionCommand>{f.proposal(),PoliticalAnswerSuccession{first,true},PoliticalWithdrawSuccession{{"city","chief",0,"leader"},second},PoliticalAccedeSuccession{"accepted","death","notice",1}}){auto kind=political_succession_command_kind(command);auto encoded=encode_political_succession_command(command);check(compare_boundary(encoded,encode_political_succession_command(take(decode_political_succession_command(kind,encoded)))).exact(),"four exact commands roundtrip without generated sources");}
 std::cout<<checks<<" checks; source fixture only, no World run claimed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

#endif
